import { Injectable, NotFoundException } from '@nestjs/common';
import { createReadStream, existsSync } from 'fs';
import { mkdir, unlink, writeFile } from 'fs/promises';
import { dirname, join, resolve } from 'path';

// Strict key shape: <orgUuid>/<randomUuid>. Keys are generated by the server only, so path
// traversal ("../") is impossible; the regex is a second line of defence.
const KEY = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

/**
 * Local-disk storage behind a tiny interface (put / stream / remove) so it can be replaced by
 * S3-compatible object storage (private bucket + SSE) without touching the callers.
 */
@Injectable()
export class StorageService {
  private readonly root = resolve(process.env.STORAGE_DIR ?? join(process.cwd(), 'storage'));

  private path(key: string): string {
    if (!KEY.test(key)) throw new Error('Invalid storage key');
    const full = resolve(this.root, key);
    if (!full.startsWith(this.root)) throw new Error('Invalid storage key');
    return full;
  }

  async put(key: string, data: Buffer): Promise<void> {
    const full = this.path(key);
    await mkdir(dirname(full), { recursive: true });
    await writeFile(full, data, { flag: 'wx', mode: 0o600 }); // never overwrite
  }

  stream(key: string) {
    const full = this.path(key);
    if (!existsSync(full)) throw new NotFoundException('File not found');
    return createReadStream(full);
  }

  async remove(key: string): Promise<void> {
    await unlink(this.path(key)).catch(() => undefined);
  }
}
